import React, { useEffect, useState } from 'react';
import NewsGrid from '../components/news/NewsGrid';
import { newsService } from '../services/newsService';
import { useNavigate } from 'react-router-dom';

const categories = ['World', 'Tech', 'Sports', 'Health'];

const HomePage = () => {
  const [articles, setArticles] = useState([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [category, setCategory] = useState('World');
  const navigate = useNavigate();

  useEffect(() => {
    const load = async () => {
      const data = await newsService.fetchNews({ category, page, pageSize: 25 });
      setArticles((prev) => (page === 1 ? data.results : [...prev, ...data.results]));
      setTotal(data.total || 0);
    };
    load();
  }, [page, category]);

  // increment page when scroll near bottom
  useEffect(() => {
    const onScroll = () => {
      // only advance page if we haven't loaded all articles
      if (
        window.innerHeight + window.pageYOffset >=
        document.body.offsetHeight - 500 &&
        articles.length < total
      ) {
        setPage((p) => p + 1);
      }
    };
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const hero = articles[0];

  const handleCategory = (cat) => {
    setCategory(cat);
    setPage(1);
    setArticles([]);
  };

  return (
    <div className="home-page container mx-auto p-4">
      {/* category tabs */}
      <div className="flex flex-wrap gap-2 mb-4">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => handleCategory(cat)}
            className={`px-3 py-1 rounded-full ${
              category === cat ? 'bg-blue-600 text-white' : 'bg-gray-200 dark:bg-gray-700'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* hero article */}
      {hero && (
        <div
          className="mb-6 cursor-pointer"
          onClick={() => navigate(`/article/${hero.id}`)}
        >
          <img src={hero.imageUrl} alt={hero.title} className="w-full h-64 object-cover rounded" />
          <h2 className="text-3xl font-bold mt-2">{hero.title}</h2>
          <p className="text-gray-600 dark:text-gray-300">{hero.description}</p>
        </div>
      )}

      {/* grid */}
      <NewsGrid articles={articles.slice(1)} />

      {articles.length === 0 && (
        <p className="text-center text-gray-500">
          No articles available. Try another category or scroll to load more.
        </p>
      )}
    </div>
  );
};

export default HomePage;
